do $content_sync$
declare rep jsonb := '{}'::jsonb; n_ins bigint; n_upd bigint; n_skip bigint;
begin
  perform pg_advisory_xact_lock(hashtext('content_sync'));
  create temp table _map_profiles on commit drop as select distinct on (sp.id) sp.id as src_id, d.id as dst_id from public_preview.profiles sp join public.profiles d on lower(sp.email::text) = lower(d.email::text) order by sp.id, d.id;
  create temp table _map_organizations on commit drop as select distinct on (sp.id) sp.id as src_id, d.id as dst_id from public_preview.organizations sp join public.organizations d on lower(sp.slug::text) = lower(d.slug::text) order by sp.id, d.id;
  -- training_catalogs
  if exists (select 1 from public_preview.training_catalogs s group by s.code having count(*) > 1) then raise exception 'content-sync: key (code) is not unique in public_preview.training_catalogs'; end if;
  if exists (select 1 from public.training_catalogs d group by d.code having count(*) > 1) then raise exception 'content-sync: key (code) is not unique in public.training_catalogs'; end if;
  update public.training_catalogs d set title = s.title, description = s.description, duration_years = s.duration_years, is_active = s.is_active, updated_at = s.updated_at from public_preview.training_catalogs s where d.code is not distinct from s.code and s.updated_at > d.updated_at and row(d.title, d.description, d.duration_years, d.is_active) is distinct from row(s.title, s.description, s.duration_years, s.is_active);
  get diagnostics n_upd = row_count;
  insert into public.training_catalogs (code, title, description, duration_years, is_active, created_at, updated_at) select s.code, s.title, s.description, s.duration_years, s.is_active, s.created_at, s.updated_at from public_preview.training_catalogs s where not exists (select 1 from public.training_catalogs d where d.code is not distinct from s.code);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.training_catalogs s where not exists (select 1 from public.training_catalogs d where d.code is not distinct from s.code);
  rep := rep || jsonb_build_object('training_catalogs', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  create temp table _map_training_catalogs on commit drop as select distinct on (s.id) s.id as src_id, d.id as dst_id from public_preview.training_catalogs s join public.training_catalogs d on d.code is not distinct from s.code order by s.id, d.id;
  -- courses
  if exists (select 1 from public_preview.courses s group by s.title, s.year, s.chapter having count(*) > 1) then raise exception 'content-sync: key (title, year, chapter) is not unique in public_preview.courses'; end if;
  if exists (select 1 from public.courses d group by d.title, d.year, d.chapter having count(*) > 1) then raise exception 'content-sync: key (title, year, chapter) is not unique in public.courses'; end if;
  update public.courses d set description = s.description, exam_part = s.exam_part, lernfelder = s.lernfelder, training_catalog_id = (select m.dst_id from _map_training_catalogs m where m.src_id = s.training_catalog_id), is_active = s.is_active, is_published = s.is_published, updated_at = s.updated_at from public_preview.courses s where d.title is not distinct from s.title and d.year is not distinct from s.year and d.chapter is not distinct from s.chapter and s.updated_at > d.updated_at and row(d.description, d.exam_part, d.lernfelder, d.training_catalog_id, d.is_active, d.is_published) is distinct from row(s.description, s.exam_part, s.lernfelder, (select m.dst_id from _map_training_catalogs m where m.src_id = s.training_catalog_id), s.is_active, s.is_published);
  get diagnostics n_upd = row_count;
  insert into public.courses (title, description, year, chapter, exam_part, lernfelder, created_by_id, training_catalog_id, is_active, is_published, created_at, updated_at) select s.title, s.description, s.year, s.chapter, s.exam_part, s.lernfelder, coalesce((select m.dst_id from _map_profiles m where m.src_id = s.created_by_id), (select p.id from public.profiles p where lower(p.email) = lower('owner@example.test'))), (select m.dst_id from _map_training_catalogs m where m.src_id = s.training_catalog_id), s.is_active, s.is_published, s.created_at, s.updated_at from public_preview.courses s where not exists (select 1 from public.courses d where d.title is not distinct from s.title and d.year is not distinct from s.year and d.chapter is not distinct from s.chapter) and (s.created_by_id is null or coalesce((select m.dst_id from _map_profiles m where m.src_id = s.created_by_id), (select p.id from public.profiles p where lower(p.email) = lower('owner@example.test'))) is not null) and (s.training_catalog_id is null or (select m.dst_id from _map_training_catalogs m where m.src_id = s.training_catalog_id) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.courses s where not exists (select 1 from public.courses d where d.title is not distinct from s.title and d.year is not distinct from s.year and d.chapter is not distinct from s.chapter);
  rep := rep || jsonb_build_object('courses', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  create temp table _map_courses on commit drop as select distinct on (s.id) s.id as src_id, d.id as dst_id from public_preview.courses s join public.courses d on d.title is not distinct from s.title and d.year is not distinct from s.year and d.chapter is not distinct from s.chapter order by s.id, d.id;
  -- enablers
  if exists (select 1 from public_preview.enablers s group by s.course_id, s.title having count(*) > 1) then raise exception 'content-sync: key (course_id, title) is not unique in public_preview.enablers'; end if;
  if exists (select 1 from public.enablers d group by d.course_id, d.title having count(*) > 1) then raise exception 'content-sync: key (course_id, title) is not unique in public.enablers'; end if;
  update public.enablers d set order_index = s.order_index, description_text = s.description_text, ppt_url = s.ppt_url, video_url = s.video_url, scenario_pdf_url = s.scenario_pdf_url, duration_value = s.duration_value, duration_unit = s.duration_unit, is_active = s.is_active, activated_at = s.activated_at, updated_at = s.updated_at from public_preview.enablers s where d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title and s.updated_at > d.updated_at and row(d.order_index, d.description_text, d.ppt_url, d.video_url, d.scenario_pdf_url, d.duration_value, d.duration_unit, d.is_active, d.activated_at) is distinct from row(s.order_index, s.description_text, s.ppt_url, s.video_url, s.scenario_pdf_url, s.duration_value, s.duration_unit, s.is_active, s.activated_at);
  get diagnostics n_upd = row_count;
  insert into public.enablers (course_id, title, order_index, description_text, ppt_url, video_url, scenario_pdf_url, duration_value, duration_unit, is_active, activated_at, created_at, updated_at) select (select m.dst_id from _map_courses m where m.src_id = s.course_id), s.title, s.order_index, s.description_text, s.ppt_url, s.video_url, s.scenario_pdf_url, s.duration_value, s.duration_unit, s.is_active, s.activated_at, s.created_at, s.updated_at from public_preview.enablers s where not exists (select 1 from public.enablers d where d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title) and (s.course_id is null or (select m.dst_id from _map_courses m where m.src_id = s.course_id) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.enablers s where not exists (select 1 from public.enablers d where d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title);
  rep := rep || jsonb_build_object('enablers', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  create temp table _map_enablers on commit drop as select distinct on (s.id) s.id as src_id, d.id as dst_id from public_preview.enablers s join public.enablers d on d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title order by s.id, d.id;
  -- use_cases
  if exists (select 1 from public_preview.use_cases s group by s.course_id, s.title having count(*) > 1) then raise exception 'content-sync: key (course_id, title) is not unique in public_preview.use_cases'; end if;
  if exists (select 1 from public.use_cases d group by d.course_id, d.title having count(*) > 1) then raise exception 'content-sync: key (course_id, title) is not unique in public.use_cases'; end if;
  update public.use_cases d set description_text = s.description_text, order_index = s.order_index, duration_value = s.duration_value, duration_unit = s.duration_unit, is_active = s.is_active, activated_at = s.activated_at, year = s.year, training_stage = s.training_stage, lernfelder = s.lernfelder, updated_at = s.updated_at from public_preview.use_cases s where d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title and s.updated_at > d.updated_at and row(d.description_text, d.order_index, d.duration_value, d.duration_unit, d.is_active, d.activated_at, d.year, d.training_stage, d.lernfelder) is distinct from row(s.description_text, s.order_index, s.duration_value, s.duration_unit, s.is_active, s.activated_at, s.year, s.training_stage, s.lernfelder);
  get diagnostics n_upd = row_count;
  insert into public.use_cases (course_id, title, description_text, order_index, duration_value, duration_unit, is_active, activated_at, year, training_stage, lernfelder, created_at, updated_at) select (select m.dst_id from _map_courses m where m.src_id = s.course_id), s.title, s.description_text, s.order_index, s.duration_value, s.duration_unit, s.is_active, s.activated_at, s.year, s.training_stage, s.lernfelder, s.created_at, s.updated_at from public_preview.use_cases s where not exists (select 1 from public.use_cases d where d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title) and (s.course_id is null or (select m.dst_id from _map_courses m where m.src_id = s.course_id) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.use_cases s where not exists (select 1 from public.use_cases d where d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title);
  rep := rep || jsonb_build_object('use_cases', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  create temp table _map_use_cases on commit drop as select distinct on (s.id) s.id as src_id, d.id as dst_id from public_preview.use_cases s join public.use_cases d on d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title order by s.id, d.id;
  -- content_documents
  if exists (select 1 from public_preview.content_documents s group by s.enabler_id, s.use_case_id, s.course_id, s.title, s.file_name, s.document_type having count(*) > 1) then raise exception 'content-sync: key (enabler_id, use_case_id, course_id, title, file_name, document_type) is not unique in public_preview.content_documents'; end if;
  if exists (select 1 from public.content_documents d group by d.enabler_id, d.use_case_id, d.course_id, d.title, d.file_name, d.document_type having count(*) > 1) then raise exception 'content-sync: key (enabler_id, use_case_id, course_id, title, file_name, document_type) is not unique in public.content_documents'; end if;
  update public.content_documents d set description = s.description, visibility = s.visibility, file_size = s.file_size, mime_type = s.mime_type, storage_url = s.storage_url, storage_path = s.storage_path, page_count = s.page_count, order_index = s.order_index, updated_at = s.updated_at from public_preview.content_documents s where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and d.use_case_id is not distinct from (select m.dst_id from _map_use_cases m where m.src_id = s.use_case_id) and d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title and d.file_name is not distinct from s.file_name and d.document_type is not distinct from s.document_type and s.updated_at > d.updated_at and row(d.description, d.visibility, d.file_size, d.mime_type, d.storage_url, d.storage_path, d.page_count, d.order_index) is distinct from row(s.description, s.visibility, s.file_size, s.mime_type, s.storage_url, s.storage_path, s.page_count, s.order_index);
  get diagnostics n_upd = row_count;
  insert into public.content_documents (enabler_id, use_case_id, course_id, organization_id, title, description, document_type, visibility, file_name, file_size, mime_type, storage_url, storage_path, page_count, order_index, uploaded_by_id, created_at, updated_at) select (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id), (select m.dst_id from _map_use_cases m where m.src_id = s.use_case_id), (select m.dst_id from _map_courses m where m.src_id = s.course_id), (select m.dst_id from _map_organizations m where m.src_id = s.organization_id), s.title, s.description, s.document_type, s.visibility, s.file_name, s.file_size, s.mime_type, s.storage_url, s.storage_path, s.page_count, s.order_index, (select m.dst_id from _map_profiles m where m.src_id = s.uploaded_by_id), s.created_at, s.updated_at from public_preview.content_documents s where not exists (select 1 from public.content_documents d where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and d.use_case_id is not distinct from (select m.dst_id from _map_use_cases m where m.src_id = s.use_case_id) and d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title and d.file_name is not distinct from s.file_name and d.document_type is not distinct from s.document_type) and (s.enabler_id is null or (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) is not null) and (s.use_case_id is null or (select m.dst_id from _map_use_cases m where m.src_id = s.use_case_id) is not null) and (s.course_id is null or (select m.dst_id from _map_courses m where m.src_id = s.course_id) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.content_documents s where not exists (select 1 from public.content_documents d where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and d.use_case_id is not distinct from (select m.dst_id from _map_use_cases m where m.src_id = s.use_case_id) and d.course_id is not distinct from (select m.dst_id from _map_courses m where m.src_id = s.course_id) and d.title is not distinct from s.title and d.file_name is not distinct from s.file_name and d.document_type is not distinct from s.document_type);
  rep := rep || jsonb_build_object('content_documents', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  -- quizzes
  if exists (select 1 from public_preview.quizzes s group by s.title, s.quiz_type, s.created_at having count(*) > 1) then raise exception 'content-sync: key (title, quiz_type, created_at) is not unique in public_preview.quizzes'; end if;
  if exists (select 1 from public.quizzes d group by d.title, d.quiz_type, d.created_at having count(*) > 1) then raise exception 'content-sync: key (title, quiz_type, created_at) is not unique in public.quizzes'; end if;
  update public.quizzes d set is_active = s.is_active, updated_at = s.updated_at from public_preview.quizzes s where d.title is not distinct from s.title and d.quiz_type is not distinct from s.quiz_type and d.created_at is not distinct from s.created_at and s.updated_at > d.updated_at and row(d.is_active) is distinct from row(s.is_active);
  get diagnostics n_upd = row_count;
  insert into public.quizzes (title, quiz_type, created_by_id, is_active, created_at, updated_at) select s.title, s.quiz_type, coalesce((select m.dst_id from _map_profiles m where m.src_id = s.created_by_id), (select p.id from public.profiles p where lower(p.email) = lower('owner@example.test'))), s.is_active, s.created_at, s.updated_at from public_preview.quizzes s where not exists (select 1 from public.quizzes d where d.title is not distinct from s.title and d.quiz_type is not distinct from s.quiz_type and d.created_at is not distinct from s.created_at) and (s.created_by_id is null or coalesce((select m.dst_id from _map_profiles m where m.src_id = s.created_by_id), (select p.id from public.profiles p where lower(p.email) = lower('owner@example.test'))) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.quizzes s where not exists (select 1 from public.quizzes d where d.title is not distinct from s.title and d.quiz_type is not distinct from s.quiz_type and d.created_at is not distinct from s.created_at);
  rep := rep || jsonb_build_object('quizzes', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  create temp table _map_quizzes on commit drop as select distinct on (s.id) s.id as src_id, d.id as dst_id from public_preview.quizzes s join public.quizzes d on d.title is not distinct from s.title and d.quiz_type is not distinct from s.quiz_type and d.created_at is not distinct from s.created_at order by s.id, d.id;
  -- enabler_quizzes
  if exists (select 1 from public_preview.enabler_quizzes s group by s.enabler_id having count(*) > 1) then raise exception 'content-sync: key (enabler_id) is not unique in public_preview.enabler_quizzes'; end if;
  if exists (select 1 from public.enabler_quizzes d group by d.enabler_id having count(*) > 1) then raise exception 'content-sync: key (enabler_id) is not unique in public.enabler_quizzes'; end if;
  update public.enabler_quizzes d set quiz_id = (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) from public_preview.enabler_quizzes s where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and row(d.quiz_id) is distinct from row((select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id));
  get diagnostics n_upd = row_count;
  insert into public.enabler_quizzes (enabler_id, quiz_id) select (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id), (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) from public_preview.enabler_quizzes s where not exists (select 1 from public.enabler_quizzes d where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id)) and (s.enabler_id is null or (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) is not null) and (s.quiz_id is null or (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.enabler_quizzes s where not exists (select 1 from public.enabler_quizzes d where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id));
  rep := rep || jsonb_build_object('enabler_quizzes', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  -- enabler_quiz_links
  if exists (select 1 from public_preview.enabler_quiz_links s group by s.enabler_id, s.difficulty having count(*) > 1) then raise exception 'content-sync: key (enabler_id, difficulty) is not unique in public_preview.enabler_quiz_links'; end if;
  if exists (select 1 from public.enabler_quiz_links d group by d.enabler_id, d.difficulty having count(*) > 1) then raise exception 'content-sync: key (enabler_id, difficulty) is not unique in public.enabler_quiz_links'; end if;
  update public.enabler_quiz_links d set quiz_id = (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) from public_preview.enabler_quiz_links s where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and d.difficulty is not distinct from s.difficulty and row(d.quiz_id) is distinct from row((select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id));
  get diagnostics n_upd = row_count;
  insert into public.enabler_quiz_links (enabler_id, quiz_id, difficulty) select (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id), (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id), s.difficulty from public_preview.enabler_quiz_links s where not exists (select 1 from public.enabler_quiz_links d where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and d.difficulty is not distinct from s.difficulty) and (s.enabler_id is null or (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) is not null) and (s.quiz_id is null or (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) is not null);
  get diagnostics n_ins = row_count;
  select count(*) into n_skip from public_preview.enabler_quiz_links s where not exists (select 1 from public.enabler_quiz_links d where d.enabler_id is not distinct from (select m.dst_id from _map_enablers m where m.src_id = s.enabler_id) and d.difficulty is not distinct from s.difficulty);
  rep := rep || jsonb_build_object('enabler_quiz_links', jsonb_build_object('inserted', n_ins, 'updated', n_upd, 'unmatched', n_skip));
  -- questions
  if exists (select 1 from public_preview.questions s group by s.quiz_id, s.order_index having count(*) > 1) then raise exception 'content-sync: key (quiz_id, order_index) is not unique in public_preview.questions'; end if;
  if exists (select 1 from public.questions d group by d.quiz_id, d.order_index having count(*) > 1) then raise exception 'content-sync: key (quiz_id, order_index) is not unique in public.questions'; end if;
  update public.questions d set question_text = s.question_text, question_type = s.question_type, expected_answer = s.expected_answer from public_preview.questions s where d.quiz_id is not distinct from (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) and d.order_index is not distinct from s.order_index and row(d.question_text, d.question_type, d.expected_answer) is distinct from row(s.question_text, s.question_type, s.expected_answer);
  get diagnostics n_upd = row_count;
  insert into public.questions (quiz_id, question_text, question_type, expected_answer, order_index) select (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id), s.question_text, s.question_type, s.expected_answer, s.order_index from public_preview.questions s where not exists (select 1 from public.questions d where d.quiz_id is not distinct from (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) and d.order_index is not distinct from s.order_index) and (s.quiz_id is null or (select m.dst_id from _map_quizzes m where m.src_id = s.quiz_id) is not null);
  get diagnostics n_ins = row_count;
